                        (_, _, _, uint ma) = dstMask.At(dmp.X + dr.Min.X + dx, dmp.Y + dr.Min.Y + dy).Rgba();
                        p = new Rgba64((ushort)((uint)p.R * ma / 0xffff), (ushort)((uint)p.G * ma / 0xffff), (ushort)((uint)p.B * ma / 0xffff), (ushort)((uint)p.A * ma / 0xffff));
