                    }
                    uint pa1 = 0xffff - pa;
                    dstColorRGBA64 = new Rgba64((ushort)(qr * pa1 / 0xffff + pr), (ushort)(qg * pa1 / 0xffff + pg), (ushort)(qb * pa1 / 0xffff + pb), (ushort)(qa * pa1 / 0xffff + pa));
                    dst.Set(dr.Min.X + dx, dr.Min.Y + dy, dstColorRGBA64);
                }
            }
        }

        internal static void NnScale_Image_Image_Src(IWritableImage dst, Rect dr, Rect adr, IImage src, Rect sr, Options o)
        {
            ulong dw2 = (ulong)dr.Dx() * 2;
            ulong dh2 = (ulong)dr.Dy() * 2;
            ulong sw = (ulong)sr.Dx();
            ulong sh = (ulong)sr.Dy();
            IImage? srcMask = o.SrcMask;
            Point smp = o.SrcMaskP;
            IImage? dstMask = o.DstMask;
            Point dmp = o.DstMaskP;
            Rgba64 dstColorRGBA64 = new Rgba64(0, 0, 0, 0);
            for (int dy = adr.Min.Y; dy < adr.Max.Y; dy++)
            {
                ulong sy = (2UL * (ulong)dy + 1) * sh / dh2;
                for (int dx = adr.Min.X; dx < adr.Max.X; dx++) { 
                    ulong sx = (2UL * (ulong)dx + 1) * sw / dw2;
                    (uint pr, uint pg, uint pb, uint pa) = src.At(sr.Min.X + (int)sx, sr.Min.Y + (int)sy).Rgba();
                    if (srcMask != null)
                    {
                        (_, _, _, uint ma) = srcMask.At(smp.X + sr.Min.X + (int)sx, smp.Y + sr.Min.Y + (int)sy).Rgba();
                        pr = pr * ma / 0xffff;
                        pg = pg * ma / 0xffff;
                        pb = pb * ma / 0xffff;
                        pa = pa * ma / 0xffff;
                    }
                    if (dstMask != null)
                    {
                        (uint qr, uint qg, uint qb, uint qa) = dst.At(dr.Min.X + dx, dr.Min.Y + dy).Rgba();
                        (_, _, _, uint ma) = dstMask.At(dmp.X + dr.Min.X + dx, dmp.Y + dr.Min.Y + dy).Rgba();
                        pr = pr * ma / 0xffff;
                        pg = pg * ma / 0xffff;
                        pb = pb * ma / 0xffff;
                        pa = pa * ma / 0xffff;
                        uint pa1 = 0xffff - ma;
                        dstColorRGBA64 = new Rgba64((ushort)(qr * pa1 / 0xffff + pr), (ushort)(qg * pa1 / 0xffff + pg), (ushort)(qb * pa1 / 0xffff + pb), (ushort)(qa * pa1 / 0xffff + pa));
                        dst.Set(dr.Min.X + dx, dr.Min.Y + dy, dstColorRGBA64);
                    }
                    else
                    {
                        dstColorRGBA64 = new Rgba64((ushort)pr, (ushort)pg, (ushort)pb, (ushort)pa);
                        dst.Set(dr.Min.X + dx, dr.Min.Y + dy, dstColorRGBA64);
                    }
                }
            }
        }

        internal static void NnTransform_Image_Image_Src(IWritableImage dst, Rect dr, Rect adr, Aff3 d2s, IImage src, Rect sr, Point bias, Options o)
        {
            IImage? srcMask = o.SrcMask;
            Point smp = o.SrcMaskP;
            IImage? dstMask = o.DstMask;
            Point dmp = o.DstMaskP;
            Rgba64 dstColorRGBA64 = new Rgba64(0, 0, 0, 0);
            for (int dy = adr.Min.Y; dy < adr.Max.Y; dy++)
            {
                double dyf = dr.Min.Y + dy + 0.5;
                for (int dx = adr.Min.X; dx < adr.Max.X; dx++) { 
                    double dxf = dr.Min.X + dx + 0.5;
                    int sx0 = (int)(d2s[0] * dxf + d2s[1] * dyf + d2s[2]) + bias.X;
                    int sy0 = (int)(d2s[3] * dxf + d2s[4] * dyf + d2s[5]) + bias.Y;
                    if (!new Point(sx0, sy0).In(sr))
                    {
                        continue;
                    }
                    (uint pr, uint pg, uint pb, uint pa) = src.At(sx0, sy0).Rgba();
                    if (srcMask != null)
                    {
                        (_, _, _, uint ma) = srcMask.At(smp.X + sx0, smp.Y + sy0).Rgba();
                        pr = pr * ma / 0xffff;
                        pg = pg * ma / 0xffff;
                        pb = pb * ma / 0xffff;
                        pa = pa * ma / 0xffff;
                    }
                    if (dstMask != null)
                    {
                        (uint qr, uint qg, uint qb, uint qa) = dst.At(dr.Min.X + dx, dr.Min.Y + dy).Rgba();
                        (_, _, _, uint ma) = dstMask.At(dmp.X + dr.Min.X + dx, dmp.Y + dr.Min.Y + dy).Rgba();
                        pr = pr * ma / 0xffff;
                        pg = pg * ma / 0xffff;
                        pb = pb * ma / 0xffff;
                        pa = pa * ma / 0xffff;
                        uint pa1 = 0xffff - ma;
                        dstColorRGBA64 = new Rgba64((ushort)(qr * pa1 / 0xffff + pr), (ushort)(qg * pa1 / 0xffff + pg), (ushort)(qb * pa1 / 0xffff + pb), (ushort)(qa * pa1 / 0xffff + pa));
                        dst.Set(dr.Min.X + dx, dr.Min.Y + dy, dstColorRGBA64);
                    }
                    else
                    {
                        dstColorRGBA64 = new Rgba64((ushort)pr, (ushort)pg, (ushort)pb, (ushort)pa);
                        dst.Set(dr.Min.X + dx, dr.Min.Y + dy, dstColorRGBA64);
                    }
                }
            }
        }



        internal static void AblScale(IWritableImage dst, Rect dr, IImage src, Rect sr, Op op, Options? opts)
        {
            // Try to simplify a Scale to a Copy when DstMask is not specified.
            // If DstMask is not nil, Copy will call Scale back with same dr and sr, and cause stack overflow.
            if (dr.Size().Eq(sr.Size()) && (opts == null || opts.Value.DstMask == null))
            {
                ScaleOps.Copy(dst, dr.Min, src, sr, op, opts);
                return;
            }

            var o = opts ?? default;

            // adr is the affected destination pixels.
            Rect adr = dst.Bounds().Intersect(dr);
            (adr, o.DstMask) = ScaleOps.ClipAffectedDestRect(adr, o.DstMask, o.DstMaskP);
            if (adr.Empty() || sr.Empty())
            {
                return;
            }
            // Make adr relative to dr.Min.
            adr = adr.Sub(dr.Min);
            if (op == Op.Over && o.SrcMask == null && ScaleOps.Opaque(src))
            {
                op = Op.Src;
            }

            // sr is the source pixels. If it extends beyond the src bounds,
            // we cannot use the type-specific fast paths, as they access
            // the Pix fields directly without bounds checking.
            //
            // Similarly, the fast paths assume that the masks are nil.
            if (o.DstMask != null || o.SrcMask != null || !sr.In(src.Bounds()))
            {
                switch (op)
                {
                    case Op.Over: AblScale_Image_Image_Over(dst, dr, adr, src, sr, o); break;
                    case Op.Src: AblScale_Image_Image_Src(dst, dr, adr, src, sr, o); break;
                }
            }
            else if (src is UniformImage)
            {
                DrawOps.Draw(dst, dr, src, src.Bounds().Min, op);
            }
            else
            {
                switch (op)
                {
                    case Op.Over:
                        switch (dst)
                        {
                            case RgbaImage d:
                                switch (src)
                                {
                                    case NrgbaImage s:
                                        AblScale_Rgba_Nrgba_Over(d, dr, adr, s, sr, o);
                                        break;
                                    case RgbaImage s:
                                        AblScale_Rgba_Rgba_Over(d, dr, adr, s, sr, o);
                                        break;
                                    case IRgba64Image s:
                                        AblScale_Rgba_Rgba64_Over(d, dr, adr, s, sr, o);
                                        break;
                                    default:
                                        AblScale_Rgba_Image_Over(d, dr, adr, src, sr, o);
                                        break;
                                }
                                break;
                            case ITargetRgba64Image d:
                                switch (src)
                                {
                                    case IRgba64Image s:
                                        AblScale_Rgba64_Rgba64_Over(d, dr, adr, s, sr, o);
                                        break;
                                }
                                break;
                            default:
                                switch (src)
                                {
                                    default:
                                        AblScale_Image_Image_Over(dst, dr, adr, src, sr, o);
                                        break;
                                }
                                break;
                        }
                        break;
                    case Op.Src:
                        switch (dst)
                        {
                            case RgbaImage d:
                                switch (src)
                                {
                                    case GrayImage s:
                                        AblScale_Rgba_Gray_Src(d, dr, adr, s, sr, o);
                                        break;
                                    case NrgbaImage s:
                                        AblScale_Rgba_Nrgba_Src(d, dr, adr, s, sr, o);
                                        break;
                                    case RgbaImage s:
                                        AblScale_Rgba_Rgba_Src(d, dr, adr, s, sr, o);
                                        break;
                                    case YCbCrImage s:
                                        switch (s.SubsampleRatio)
                                        {
                                            default:
                                                AblScale_Rgba_Image_Src(d, dr, adr, s, sr, o);
                                                break;
                                            case YCbCrSubsampleRatio.Ratio444:
                                                AblScale_Rgba_YCbCr444_Src(d, dr, adr, s, sr, o);
                                                break;
                                            case YCbCrSubsampleRatio.Ratio422:
                                                AblScale_Rgba_YCbCr422_Src(d, dr, adr, s, sr, o);
                                                break;
                                            case YCbCrSubsampleRatio.Ratio420:
                                                AblScale_Rgba_YCbCr420_Src(d, dr, adr, s, sr, o);
                                                break;
                                            case YCbCrSubsampleRatio.Ratio440:
                                                AblScale_Rgba_YCbCr440_Src(d, dr, adr, s, sr, o);
                                                break;
                                        }
                                        break;
                                    case IRgba64Image s:
                                        AblScale_Rgba_Rgba64_Src(d, dr, adr, s, sr, o);
                                        break;
                                    default:
                                        AblScale_Rgba_Image_Src(d, dr, adr, src, sr, o);
                                        break;
                                }
                                break;
                            case ITargetRgba64Image d:
                                switch (src)
                                {
                                    case IRgba64Image s:
                                        AblScale_Rgba64_Rgba64_Src(d, dr, adr, s, sr, o);
                                        break;
                                }
                                break;
                            default:
                                switch (src)
                                {
                                    default:
                                        AblScale_Image_Image_Src(dst, dr, adr, src, sr, o);
                                        break;
                                }
                                break;
                        }
                        break;
                }

            }
        }

        internal static void AblTransform(IWritableImage dst, Aff3 s2d, IImage src, Rect sr, Op op, Options? opts)
        {
            // Try to simplify a Transform to a Copy.
            if (s2d[0] == 1 && s2d[1] == 0 && s2d[3] == 0 && s2d[4] == 1)
            {
                int dx = (int)s2d[2];
                int dy = (int)s2d[5];
                if ((double)dx == s2d[2] && (double)dy == s2d[5])
                {
                    ScaleOps.Copy(dst, new Point(sr.Min.X + dx, sr.Min.X + dy), src, sr, op, opts);
                    return;
                }
            }

            var o = opts ?? default;

            Rect dr = TransformRect(s2d, sr);
            // adr is the affected destination pixels.
            Rect adr = dst.Bounds().Intersect(dr);
            (adr, o.DstMask) = ScaleOps.ClipAffectedDestRect(adr, o.DstMask, o.DstMaskP);
            if (adr.Empty() || sr.Empty())
            {
                return;
            }
            if (op == Op.Over && o.SrcMask == null && ScaleOps.Opaque(src))
            {
                op = Op.Src;
            }

            var d2s = Invert(s2d);
            // bias is a translation of the mapping from dst coordinates to src
            // coordinates such that the latter temporarily have non-negative X
            // and Y coordinates. This allows us to write int(f) instead of
            // int(math.Floor(f)), since "round to zero" and "round down" are
            // equivalent when f >= 0, but the former is much cheaper. The X--
            // and Y-- are because the TransformLeaf methods have a "sx -= 0.5"
            // adjustment.
            Point bias = TransformRect(d2s, adr).Min;
            bias = new Point(bias.X - 1, bias.Y - 1);
            d2s = new Aff3(d2s[0], d2s[1], d2s[2] - bias.X, d2s[3], d2s[4], d2s[5] - bias.Y);
            // Make adr relative to dr.Min.
            adr = adr.Sub(dr.Min);

            // sr is the source pixels. If it extends beyond the src bounds,
            // we cannot use the type-specific fast paths, as they access
            // the Pix fields directly without bounds checking.
            //
            // Similarly, the fast paths assume that the masks are nil.
            if (o.DstMask != null || o.SrcMask != null || !sr.In(src.Bounds()))
            {
                switch (op)
                {
                    case Op.Over: AblTransform_Image_Image_Over(dst, dr, adr, d2s, src, sr, bias, o); break;
                    case Op.Src: AblTransform_Image_Image_Src(dst, dr, adr, d2s, src, sr, bias, o); break;
                }
            }
            else if (src is UniformImage u)
            {
                TransformUniform(dst, dr, adr, d2s, u, sr, bias, op);
            }
            else
            {
                switch (op)
                {
                    case Op.Over:
                        switch (dst)
                        {
                            case RgbaImage d:
                                switch (src)
                                {
                                    case NrgbaImage s:
                                        AblTransform_Rgba_Nrgba_Over(d, dr, adr, d2s, s, sr, bias, o);
                                        break;
                                    case RgbaImage s:
                                        AblTransform_Rgba_Rgba_Over(d, dr, adr, d2s, s, sr, bias, o);
                                        break;
                                    case IRgba64Image s:
                                        AblTransform_Rgba_Rgba64_Over(d, dr, adr, d2s, s, sr, bias, o);
                                        break;
                                    default:
                                        AblTransform_Rgba_Image_Over(d, dr, adr, d2s, src, sr, bias, o);
                                        break;
                                }
                                break;
                            case ITargetRgba64Image d:
                                switch (src)
                                {
                                    case IRgba64Image s:
                                        AblTransform_Rgba64_Rgba64_Over(d, dr, adr, d2s, s, sr, bias, o);
                                        break;
                                }
                                break;
                            default:
                                switch (src)
                                {
                                    default:
                                        AblTransform_Image_Image_Over(dst, dr, adr, d2s, src, sr, bias, o);
                                        break;
                                }
                                break;
                        }
                        break;
                    case Op.Src:
                        switch (dst)
                        {
                            case RgbaImage d:
                                switch (src)
                                {
                                    case GrayImage s:
                                        AblTransform_Rgba_Gray_Src(d, dr, adr, d2s, s, sr, bias, o);
                                        break;
                                    case NrgbaImage s:
                                        AblTransform_Rgba_Nrgba_Src(d, dr, adr, d2s, s, sr, bias, o);
                                        break;
                                    case RgbaImage s:
                                        AblTransform_Rgba_Rgba_Src(d, dr, adr, d2s, s, sr, bias, o);
                                        break;
                                    case YCbCrImage s:
                                        switch (s.SubsampleRatio)
                                        {
                                            default:
                                                AblTransform_Rgba_Image_Src(d, dr, adr, d2s, s, sr, bias, o);
                                                break;
                                            case YCbCrSubsampleRatio.Ratio444:
                                                AblTransform_Rgba_YCbCr444_Src(d, dr, adr, d2s, s, sr, bias, o);
                                                break;
                                            case YCbCrSubsampleRatio.Ratio422:
                                                AblTransform_Rgba_YCbCr422_Src(d, dr, adr, d2s, s, sr, bias, o);
                                                break;
                                            case YCbCrSubsampleRatio.Ratio420:
                                                AblTransform_Rgba_YCbCr420_Src(d, dr, adr, d2s, s, sr, bias, o);
                                                break;
                                            case YCbCrSubsampleRatio.Ratio440:
                                                AblTransform_Rgba_YCbCr440_Src(d, dr, adr, d2s, s, sr, bias, o);
                                                break;
                                        }
                                        break;
                                    case IRgba64Image s:
                                        AblTransform_Rgba_Rgba64_Src(d, dr, adr, d2s, s, sr, bias, o);
                                        break;
                                    default:
                                        AblTransform_Rgba_Image_Src(d, dr, adr, d2s, src, sr, bias, o);
                                        break;
                                }
                                break;
                            case ITargetRgba64Image d:
                                switch (src)
                                {
                                    case IRgba64Image s:
                                        AblTransform_Rgba64_Rgba64_Src(d, dr, adr, d2s, s, sr, bias, o);
                                        break;
                                }
                                break;
                            default:
                                switch (src)
                                {
                                    default:
                                        AblTransform_Image_Image_Src(dst, dr, adr, d2s, src, sr, bias, o);
                                        break;
                                }
                                break;
                        }
                        break;
                }

            }
        }

        internal static void AblScale_Rgba_Gray_Src(RgbaImage dst, Rect dr, Rect adr, GrayImage src, Rect sr, Options o)
        {
            int sw = sr.Dx();
            int sh = sr.Dy();
            double yscale = (double)sh / dr.Dy();
            double xscale = (double)sw / dr.Dx();
            int swMinus1 = sw - 1, shMinus1 = sh - 1;

            for (int dy = adr.Min.Y; dy < adr.Max.Y; dy++)
            {
                double sy = (dy + 0.5) * yscale - 0.5;
                // If sy < 0, we will clamp sy0 to 0 anyway, so it doesn't matter if
                // we truncate instead of flooring.
                int sy0 = (int)sy;
                double yFrac0 = sy - sy0;
                double yFrac1 = 1 - yFrac0;
                int sy1 = sy0 + 1;
                if (sy < 0)
                {
                    sy0 = 0;
                    sy1 = 0;
                    yFrac0 = 0;
                    yFrac1 = 1;
                }
                else if (sy1 > shMinus1)
                {
                    sy0 = shMinus1;
                    sy1 = shMinus1;
                    yFrac0 = 1;
                    yFrac1 = 0;
                }
                int d = (dr.Min.Y+dy-dst.Rect.Min.Y)*dst.Stride + (dr.Min.X+adr.Min.X-dst.Rect.Min.X)*4;

                for (int dx = adr.Min.X; dx < adr.Max.X; dx++, d += 4) { 
                    double sx = (dx + 0.5) * xscale - 0.5;
                    int sx0 = (int)sx;
                    double xFrac0 = sx - sx0;
                    double xFrac1 = 1 - xFrac0;
                    int sx1 = sx0 + 1;
                    if (sx < 0)
                    {
                        sx0 = 0;
                        sx1 = 0;
                        xFrac0 = 0;
                        xFrac1 = 1;
                    }
                    else if (sx1 > swMinus1)
                    {
                        sx0 = swMinus1;
                        sx1 = swMinus1;
                        xFrac0 = 1;
                        xFrac1 = 0;
                    }

                    int s00i = (sr.Min.Y + sy0-src.Rect.Min.Y)*src.Stride + (sr.Min.X + sx0-src.Rect.Min.X);
                    uint s00ru = (uint)src.Pix.Span[s00i] * 0x101;
                    double s00r = (double)s00ru;
                    int s10i = (sr.Min.Y + sy0-src.Rect.Min.Y)*src.Stride + (sr.Min.X + sx1-src.Rect.Min.X);
                    uint s10ru = (uint)src.Pix.Span[s10i] * 0x101;
                    double s10r = (double)s10ru;
                    s10r = xFrac1 * s00r + xFrac0 * s10r;
                    int s01i = (sr.Min.Y + sy1-src.Rect.Min.Y)*src.Stride + (sr.Min.X + sx0-src.Rect.Min.X);
                    uint s01ru = (uint)src.Pix.Span[s01i] * 0x101;
                    double s01r = (double)s01ru;
                    int s11i = (sr.Min.Y + sy1-src.Rect.Min.Y)*src.Stride + (sr.Min.X + sx1-src.Rect.Min.X);
                    uint s11ru = (uint)src.Pix.Span[s11i] * 0x101;
                    double s11r = (double)s11ru;
                    s11r = xFrac1 * s01r + xFrac0 * s11r;
                    s11r = yFrac1 * s10r + yFrac0 * s11r;
                    uint pr = (uint)s11r;
                    byte Out = (byte)(pr >> 8);
                    dst.Pix.Span[d + 0] = Out;
                    dst.Pix.Span[d + 1] = Out;
                    dst.Pix.Span[d + 2] = Out;
                    dst.Pix.Span[d + 3] = 0xff;
                }
            }
        }

        internal static void AblTransform_Rgba_Gray_Src(RgbaImage dst, Rect dr, Rect adr, Aff3 d2s, GrayImage src, Rect sr, Point bias, Options o)
        {
            for (int dy = adr.Min.Y; dy < adr.Max.Y; dy++)
            {
                double dyf = dr.Min.Y + dy + 0.5;
                int d = (dr.Min.Y+dy-dst.Rect.Min.Y)*dst.Stride + (dr.Min.X+adr.Min.X-dst.Rect.Min.X)*4;
                for (int dx = adr.Min.X; dx < adr.Max.X; dx++, d += 4) { 
                    double dxf = dr.Min.X + dx + 0.5;
                    double sx = d2s[0] * dxf + d2s[1] * dyf + d2s[2];
                    double sy = d2s[3] * dxf + d2s[4] * dyf + d2s[5];
                    if (!new Point((int)sx + bias.X, (int)sy + bias.Y).In(sr))
                    {
                        continue;
                    }

                    sx -= 0.5;
                    int sx0 = (int)sx;
                    double xFrac0 = sx - sx0;
                    double xFrac1 = 1 - xFrac0;
                    sx0 += bias.X;
                    int sx1 = sx0 + 1;
                    if (sx0 < sr.Min.X)
                    {
                        sx0 = sr.Min.X;
                        sx1 = sr.Min.X;
                        xFrac0 = 0;
                        xFrac1 = 1;
                    }
                    else if (sx1 >= sr.Max.X)
                    {
                        sx0 = sr.Max.X - 1;
                        sx1 = sr.Max.X - 1;
                        xFrac0 = 1;
                        xFrac1 = 0;
                    }

                    sy -= 0.5;
                    int sy0 = (int)sy;
                    double yFrac0 = sy - sy0;
                    double yFrac1 = 1 - yFrac0;
                    sy0 += bias.Y;
                    int sy1 = sy0 + 1;
                    if (sy0 < sr.Min.Y)
                    {
                        sy0 = sr.Min.Y;
                        sy1 = sr.Min.Y;
                        yFrac0 = 0;
                        yFrac1 = 1;
                    }
                    else if (sy1 >= sr.Max.Y)
                    {
                        sy0 = sr.Max.Y - 1;
                        sy1 = sr.Max.Y - 1;
                        yFrac0 = 1;
                        yFrac1 = 0;
                    }

                    int s00i = (sy0-src.Rect.Min.Y)*src.Stride + (sx0-src.Rect.Min.X);
                    uint s00ru = (uint)src.Pix.Span[s00i] * 0x101;
                    double s00r = (double)s00ru;
                    int s10i = (sy0-src.Rect.Min.Y)*src.Stride + (sx1-src.Rect.Min.X);
                    uint s10ru = (uint)src.Pix.Span[s10i] * 0x101;
                    double s10r = (double)s10ru;
                    s10r = xFrac1 * s00r + xFrac0 * s10r;
                    int s01i = (sy1-src.Rect.Min.Y)*src.Stride + (sx0-src.Rect.Min.X);
                    uint s01ru = (uint)src.Pix.Span[s01i] * 0x101;
                    double s01r = (double)s01ru;
                    int s11i = (sy1-src.Rect.Min.Y)*src.Stride + (sx1-src.Rect.Min.X);
                    uint s11ru = (uint)src.Pix.Span[s11i] * 0x101;
                    double s11r = (double)s11ru;
                    s11r = xFrac1 * s01r + xFrac0 * s11r;
                    s11r = yFrac1 * s10r + yFrac0 * s11r;
                    uint pr = (uint)s11r;
                    byte Out = (byte)(pr >> 8);
                    dst.Pix.Span[d + 0] = Out;
                    dst.Pix.Span[d + 1] = Out;
                    dst.Pix.Span[d + 2] = Out;
                    dst.Pix.Span[d + 3] = 0xff;
                }
            }
        }

