        internal static void AblScale_Rgba_Rgba64_Over(RgbaImage dst, Rect dr, Rect adr, IRgba64Image src, Rect sr, Options o)
        {
            int sw = sr.Dx();
            int sh = sr.Dy();
            double yscale = (double)sh / dr.Dy();
            double xscale = (double)sw / dr.Dx();
            int swMinus1 = sw - 1, shMinus1 = sh - 1;

            for (int dy = adr.Min.Y; dy < adr.Max.Y; dy++)
            {
                double sy = (dy + 0.5) * yscale - 0.5;
                // If sy < 0, we will clamp sy0 to 0 anyway, so it doesn't matter if
                // we truncate instead of flooring.
                int sy0 = (int)sy;
                double yFrac0 = sy - sy0;
                double yFrac1 = 1 - yFrac0;
                int sy1 = sy0 + 1;
                if (sy < 0)
                {
                    sy0 = 0;
                    sy1 = 0;
                    yFrac0 = 0;
                    yFrac1 = 1;
                }
                else if (sy1 > shMinus1)
                {
                    sy0 = shMinus1;
                    sy1 = shMinus1;
                    yFrac0 = 1;
                    yFrac1 = 0;
                }
                int d = (dr.Min.Y+dy-dst.Rect.Min.Y)*dst.Stride + (dr.Min.X+adr.Min.X-dst.Rect.Min.X)*4;

                for (int dx = adr.Min.X; dx < adr.Max.X; dx++, d += 4) { 
                    double sx = (dx + 0.5) * xscale - 0.5;
                    int sx0 = (int)sx;
                    double xFrac0 = sx - sx0;
                    double xFrac1 = 1 - xFrac0;
                    int sx1 = sx0 + 1;
                    if (sx < 0)
                    {
                        sx0 = 0;
                        sx1 = 0;
                        xFrac0 = 0;
                        xFrac1 = 1;
                    }
                    else if (sx1 > swMinus1)
                    {
                        sx0 = swMinus1;
                        sx1 = swMinus1;
                        xFrac0 = 1;
                        xFrac1 = 0;
                    }

                    Rgba64 s00u = src.Rgba64At(sr.Min.X + sx0, sr.Min.Y + sy0);
                    double s00r = (double)s00u.R;
                    double s00g = (double)s00u.G;
                    double s00b = (double)s00u.B;
                    double s00a = (double)s00u.A;
                    Rgba64 s10u = src.Rgba64At(sr.Min.X + sx1, sr.Min.Y + sy0);
                    double s10r = (double)s10u.R;
                    double s10g = (double)s10u.G;
                    double s10b = (double)s10u.B;
                    double s10a = (double)s10u.A;
                    s10r = xFrac1 * s00r + xFrac0 * s10r;
                    s10g = xFrac1 * s00g + xFrac0 * s10g;
                    s10b = xFrac1 * s00b + xFrac0 * s10b;
                    s10a = xFrac1 * s00a + xFrac0 * s10a;
                    Rgba64 s01u = src.Rgba64At(sr.Min.X + sx0, sr.Min.Y + sy1);
                    double s01r = (double)s01u.R;
                    double s01g = (double)s01u.G;
                    double s01b = (double)s01u.B;
                    double s01a = (double)s01u.A;
                    Rgba64 s11u = src.Rgba64At(sr.Min.X + sx1, sr.Min.Y + sy1);
                    double s11r = (double)s11u.R;
                    double s11g = (double)s11u.G;
                    double s11b = (double)s11u.B;
                    double s11a = (double)s11u.A;
                    s11r = xFrac1 * s01r + xFrac0 * s11r;
                    s11g = xFrac1 * s01g + xFrac0 * s11g;
                    s11b = xFrac1 * s01b + xFrac0 * s11b;
                    s11a = xFrac1 * s01a + xFrac0 * s11a;
                    s11r = yFrac1 * s10r + yFrac0 * s11r;
                    s11g = yFrac1 * s10g + yFrac0 * s11g;
                    s11b = yFrac1 * s10b + yFrac0 * s11b;
                    s11a = yFrac1 * s10a + yFrac0 * s11a;
                    Rgba64 p = new Rgba64((ushort)s11r, (ushort)s11g, (ushort)s11b, (ushort)s11a);
                    uint pa1 = (0xffffu - p.A) * 0x101u;
                    dst.Pix.Span[d + 0] = (byte)(((uint)dst.Pix.Span[d + 0] * pa1 / 0xffff + p.R) >> 8);
                    dst.Pix.Span[d + 1] = (byte)(((uint)dst.Pix.Span[d + 1] * pa1 / 0xffff + p.G) >> 8);
                    dst.Pix.Span[d + 2] = (byte)(((uint)dst.Pix.Span[d + 2] * pa1 / 0xffff + p.B) >> 8);
                    dst.Pix.Span[d + 3] = (byte)(((uint)dst.Pix.Span[d + 3] * pa1 / 0xffff + p.A) >> 8);
                }
