                        s11bu = s11bu * ma / 0xffff;
                        s11au = s11au * ma / 0xffff;
                    }
                    double s11r = (double)s11ru;
                    double s11g = (double)s11gu;
                    double s11b = (double)s11bu;
                    double s11a = (double)s11au;
                    s11r = xFrac1 * s01r + xFrac0 * s11r;
                    s11g = xFrac1 * s01g + xFrac0 * s11g;
                    s11b = xFrac1 * s01b + xFrac0 * s11b;
                    s11a = xFrac1 * s01a + xFrac0 * s11a;
                    s11r = yFrac1 * s10r + yFrac0 * s11r;
                    s11g = yFrac1 * s10g + yFrac0 * s11g;
                    s11b = yFrac1 * s10b + yFrac0 * s11b;
                    s11a = yFrac1 * s10a + yFrac0 * s11a;
                    uint pr = (uint)s11r;
                    uint pg = (uint)s11g;
                    uint pb = (uint)s11b;
                    uint pa = (uint)s11a;
                    (uint qr, uint qg, uint qb, uint qa) = dst.At(dr.Min.X + dx, dr.Min.Y + dy).Rgba();
                    if (dstMask != null)
                    {
                        (_, _, _, uint ma) = dstMask.At(dmp.X + dr.Min.X + dx, dmp.Y + dr.Min.Y + dy).Rgba();
                        pr = pr * ma / 0xffff;
                        pg = pg * ma / 0xffff;
                        pb = pb * ma / 0xffff;
                        pa = pa * ma / 0xffff;
                    }
                    uint pa1 = 0xffff - pa;
                    dstColorRGBA64 = new Rgba64((ushort)(qr * pa1 / 0xffff + pr), (ushort)(qg * pa1 / 0xffff + pg), (ushort)(qb * pa1 / 0xffff + pb), (ushort)(qa * pa1 / 0xffff + pa));
                    dst.Set(dr.Min.X + dx, dr.Min.Y + dy, dstColorRGBA64);
                }
            }
        }

