                    s10b = xFrac1 * s00b + xFrac0 * s10b;
                    s10a = xFrac1 * s00a + xFrac0 * s10a;
                    (uint s01ru, uint s01gu, uint s01bu, uint s01au) = src.At(sx0, sy1).Rgba();
                    if (srcMask != null)
                    {
                        (_, _, _, uint ma) = srcMask.At(smp.X + sx0, smp.Y + sy1).Rgba();
                        s01ru = s01ru * ma / 0xffff;
                        s01gu = s01gu * ma / 0xffff;
                        s01bu = s01bu * ma / 0xffff;
                        s01au = s01au * ma / 0xffff;
                    }
                    double s01r = (double)s01ru;
                    double s01g = (double)s01gu;
                    double s01b = (double)s01bu;
                    double s01a = (double)s01au;
                    (uint s11ru, uint s11gu, uint s11bu, uint s11au) = src.At(sx1, sy1).Rgba();
                    if (srcMask != null)
                    {
                        (_, _, _, uint ma) = srcMask.At(smp.X + sx1, smp.Y + sy1).Rgba();
                        s11ru = s11ru * ma / 0xffff;
                        s11gu = s11gu * ma / 0xffff;
                        s11bu = s11bu * ma / 0xffff;
                        s11au = s11au * ma / 0xffff;
                    }
                    double s11r = (double)s11ru;
                    double s11g = (double)s11gu;
                    double s11b = (double)s11bu;
                    double s11a = (double)s11au;
                    s11r = xFrac1 * s01r + xFrac0 * s11r;
                    s11g = xFrac1 * s01g + xFrac0 * s11g;
                    s11b = xFrac1 * s01b + xFrac0 * s11b;
                    s11a = xFrac1 * s01a + xFrac0 * s11a;
                    s11r = yFrac1 * s10r + yFrac0 * s11r;
                    s11g = yFrac1 * s10g + yFrac0 * s11g;
                    s11b = yFrac1 * s10b + yFrac0 * s11b;
                    s11a = yFrac1 * s10a + yFrac0 * s11a;
                    uint pr = (uint)s11r;
                    uint pg = (uint)s11g;
                    uint pb = (uint)s11b;
                    uint pa = (uint)s11a;
                    (uint qr, uint qg, uint qb, uint qa) = dst.At(dr.Min.X + dx, dr.Min.Y + dy).Rgba();
                    if (dstMask != null)
                    {
                        (_, _, _, uint ma) = dstMask.At(dmp.X + dr.Min.X + dx, dmp.Y + dr.Min.Y + dy).Rgba();
                        pr = pr * ma / 0xffff;
                        pg = pg * ma / 0xffff;
                        pb = pb * ma / 0xffff;
                        pa = pa * ma / 0xffff;
                    }
                    uint pa1 = 0xffff - pa;
                    dstColorRGBA64 = new Rgba64((ushort)(qr * pa1 / 0xffff + pr), (ushort)(qg * pa1 / 0xffff + pg), (ushort)(qb * pa1 / 0xffff + pb), (ushort)(qa * pa1 / 0xffff + pa));
                    dst.Set(dr.Min.X + dx, dr.Min.Y + dy, dstColorRGBA64);
                }
            }
        }

        internal static void AblScale_Image_Image_Src(IWritableImage dst, Rect dr, Rect adr, IImage src, Rect sr, Options o)
        {
            int sw = sr.Dx();
            int sh = sr.Dy();
            double yscale = (double)sh / dr.Dy();
            double xscale = (double)sw / dr.Dx();
            int swMinus1 = sw - 1, shMinus1 = sh - 1;
            IImage? srcMask = o.SrcMask;
            Point smp = o.SrcMaskP;
            IImage? dstMask = o.DstMask;
            Point dmp = o.DstMaskP;
            Rgba64 dstColorRGBA64 = new Rgba64(0, 0, 0, 0);

            for (int dy = adr.Min.Y; dy < adr.Max.Y; dy++)
            {
                double sy = (dy + 0.5) * yscale - 0.5;
                // If sy < 0, we will clamp sy0 to 0 anyway, so it doesn't matter if
                // we truncate instead of flooring.
                int sy0 = (int)sy;
                double yFrac0 = sy - sy0;
                double yFrac1 = 1 - yFrac0;
                int sy1 = sy0 + 1;
                if (sy < 0)
                {
                    sy0 = 0;
                    sy1 = 0;
                    yFrac0 = 0;
                    yFrac1 = 1;
                }
                else if (sy1 > shMinus1)
                {
                    sy0 = shMinus1;
                    sy1 = shMinus1;
                    yFrac0 = 1;
                    yFrac1 = 0;
                }

                for (int dx = adr.Min.X; dx < adr.Max.X; dx++) { 
                    double sx = (dx + 0.5) * xscale - 0.5;
                    int sx0 = (int)sx;
                    double xFrac0 = sx - sx0;
                    double xFrac1 = 1 - xFrac0;
                    int sx1 = sx0 + 1;
                    if (sx < 0)
                    {
                        sx0 = 0;
                        sx1 = 0;
                        xFrac0 = 0;
                        xFrac1 = 1;
                    }
                    else if (sx1 > swMinus1)
                    {
                        sx0 = swMinus1;
                        sx1 = swMinus1;
                        xFrac0 = 1;
                        xFrac1 = 0;
                    }

                    (uint s00ru, uint s00gu, uint s00bu, uint s00au) = src.At(sr.Min.X + sx0, sr.Min.Y + sy0).Rgba();
                    if (srcMask != null)
                    {
                        (_, _, _, uint ma) = srcMask.At(smp.X + sr.Min.X + sx0, smp.Y + sr.Min.Y + sy0).Rgba();
                        s00ru = s00ru * ma / 0xffff;
                        s00gu = s00gu * ma / 0xffff;
                        s00bu = s00bu * ma / 0xffff;
                        s00au = s00au * ma / 0xffff;
                    }
                    double s00r = (double)s00ru;
                    double s00g = (double)s00gu;
                    double s00b = (double)s00bu;
                    double s00a = (double)s00au;
                    (uint s10ru, uint s10gu, uint s10bu, uint s10au) = src.At(sr.Min.X + sx1, sr.Min.Y + sy0).Rgba();
                    if (srcMask != null)
                    {
                        (_, _, _, uint ma) = srcMask.At(smp.X + sr.Min.X + sx1, smp.Y + sr.Min.Y + sy0).Rgba();
                        s10ru = s10ru * ma / 0xffff;
                        s10gu = s10gu * ma / 0xffff;
                        s10bu = s10bu * ma / 0xffff;
                        s10au = s10au * ma / 0xffff;
                    }
                    double s10r = (double)s10ru;
                    double s10g = (double)s10gu;
                    double s10b = (double)s10bu;
                    double s10a = (double)s10au;
                    s10r = xFrac1 * s00r + xFrac0 * s10r;
                    s10g = xFrac1 * s00g + xFrac0 * s10g;
                    s10b = xFrac1 * s00b + xFrac0 * s10b;
                    s10a = xFrac1 * s00a + xFrac0 * s10a;
                    (uint s01ru, uint s01gu, uint s01bu, uint s01au) = src.At(sr.Min.X + sx0, sr.Min.Y + sy1).Rgba();
                    if (srcMask != null)
                    {
                        (_, _, _, uint ma) = srcMask.At(smp.X + sr.Min.X + sx0, smp.Y + sr.Min.Y + sy1).Rgba();
                        s01ru = s01ru * ma / 0xffff;
                        s01gu = s01gu * ma / 0xffff;
                        s01bu = s01bu * ma / 0xffff;
                        s01au = s01au * ma / 0xffff;
                    }
                    double s01r = (double)s01ru;
                    double s01g = (double)s01gu;
                    double s01b = (double)s01bu;
                    double s01a = (double)s01au;
                    (uint s11ru, uint s11gu, uint s11bu, uint s11au) = src.At(sr.Min.X + sx1, sr.Min.Y + sy1).Rgba();
                    if (srcMask != null)
                    {
                        (_, _, _, uint ma) = srcMask.At(smp.X + sr.Min.X + sx1, smp.Y + sr.Min.Y + sy1).Rgba();
                        s11ru = s11ru * ma / 0xffff;
                        s11gu = s11gu * ma / 0xffff;
                        s11bu = s11bu * ma / 0xffff;
                        s11au = s11au * ma / 0xffff;
                    }
                    double s11r = (double)s11ru;
                    double s11g = (double)s11gu;
                    double s11b = (double)s11bu;
                    double s11a = (double)s11au;
                    s11r = xFrac1 * s01r + xFrac0 * s11r;
                    s11g = xFrac1 * s01g + xFrac0 * s11g;
                    s11b = xFrac1 * s01b + xFrac0 * s11b;
                    s11a = xFrac1 * s01a + xFrac0 * s11a;
                    s11r = yFrac1 * s10r + yFrac0 * s11r;
                    s11g = yFrac1 * s10g + yFrac0 * s11g;
                    s11b = yFrac1 * s10b + yFrac0 * s11b;
                    s11a = yFrac1 * s10a + yFrac0 * s11a;
                    uint pr = (uint)s11r;
                    uint pg = (uint)s11g;
                    uint pb = (uint)s11b;
                    uint pa = (uint)s11a;
                    if (dstMask != null)
                    {
                        (uint qr, uint qg, uint qb, uint qa) = dst.At(dr.Min.X + dx, dr.Min.Y + dy).Rgba();
                        (_, _, _, uint ma) = dstMask.At(dmp.X + dr.Min.X + dx, dmp.Y + dr.Min.Y + dy).Rgba();
                        pr = pr * ma / 0xffff;
                        pg = pg * ma / 0xffff;
                        pb = pb * ma / 0xffff;
                        pa = pa * ma / 0xffff;
                        uint pa1 = 0xffff - ma;
                        dstColorRGBA64 = new Rgba64((ushort)(qr * pa1 / 0xffff + pr), (ushort)(qg * pa1 / 0xffff + pg), (ushort)(qb * pa1 / 0xffff + pb), (ushort)(qa * pa1 / 0xffff + pa));
                        dst.Set(dr.Min.X + dx, dr.Min.Y + dy, dstColorRGBA64);
                    }
                    else
                    {
                        dstColorRGBA64 = new Rgba64((ushort)pr, (ushort)pg, (ushort)pb, (ushort)pa);
                        dst.Set(dr.Min.X + dx, dr.Min.Y + dy, dstColorRGBA64);
                    }
                }
            }
        }

        internal static void AblTransform_Image_Image_Src(IWritableImage dst, Rect dr, Rect adr, Aff3 d2s, IImage src, Rect sr, Point bias, Options o)
        {
            IImage? srcMask = o.SrcMask;
            Point smp = o.SrcMaskP;
            IImage? dstMask = o.DstMask;
            Point dmp = o.DstMaskP;
            Rgba64 dstColorRGBA64 = new Rgba64(0, 0, 0, 0);
            for (int dy = adr.Min.Y; dy < adr.Max.Y; dy++)
            {
                double dyf = dr.Min.Y + dy + 0.5;
                for (int dx = adr.Min.X; dx < adr.Max.X; dx++) { 
                    double dxf = dr.Min.X + dx + 0.5;
                    double sx = d2s[0] * dxf + d2s[1] * dyf + d2s[2];
                    double sy = d2s[3] * dxf + d2s[4] * dyf + d2s[5];
                    if (!new Point((int)sx + bias.X, (int)sy + bias.Y).In(sr))
                    {
                        continue;
                    }

                    sx -= 0.5;
                    int sx0 = (int)sx;
                    double xFrac0 = sx - sx0;
                    double xFrac1 = 1 - xFrac0;
                    sx0 += bias.X;
                    int sx1 = sx0 + 1;
                    if (sx0 < sr.Min.X)
                    {
                        sx0 = sr.Min.X;
                        sx1 = sr.Min.X;
                        xFrac0 = 0;
                        xFrac1 = 1;
                    }
                    else if (sx1 >= sr.Max.X)
                    {
                        sx0 = sr.Max.X - 1;
                        sx1 = sr.Max.X - 1;
                        xFrac0 = 1;
                        xFrac1 = 0;
                    }

                    sy -= 0.5;
                    int sy0 = (int)sy;
                    double yFrac0 = sy - sy0;
                    double yFrac1 = 1 - yFrac0;
                    sy0 += bias.Y;
                    int sy1 = sy0 + 1;
                    if (sy0 < sr.Min.Y)
                    {
                        sy0 = sr.Min.Y;
                        sy1 = sr.Min.Y;
                        yFrac0 = 0;
                        yFrac1 = 1;
                    }
                    else if (sy1 >= sr.Max.Y)
                    {
                        sy0 = sr.Max.Y - 1;
                        sy1 = sr.Max.Y - 1;
                        yFrac0 = 1;
                        yFrac1 = 0;
                    }

                    (uint s00ru, uint s00gu, uint s00bu, uint s00au) = src.At(sx0, sy0).Rgba();
                    if (srcMask != null)
                    {
                        (_, _, _, uint ma) = srcMask.At(smp.X + sx0, smp.Y + sy0).Rgba();
                        s00ru = s00ru * ma / 0xffff;
                        s00gu = s00gu * ma / 0xffff;
                        s00bu = s00bu * ma / 0xffff;
                        s00au = s00au * ma / 0xffff;
                    }
                    double s00r = (double)s00ru;
                    double s00g = (double)s00gu;
                    double s00b = (double)s00bu;
                    double s00a = (double)s00au;
                    (uint s10ru, uint s10gu, uint s10bu, uint s10au) = src.At(sx1, sy0).Rgba();
                    if (srcMask != null)
                    {
                        (_, _, _, uint ma) = srcMask.At(smp.X + sx1, smp.Y + sy0).Rgba();
                        s10ru = s10ru * ma / 0xffff;
                        s10gu = s10gu * ma / 0xffff;
                        s10bu = s10bu * ma / 0xffff;
                        s10au = s10au * ma / 0xffff;
                    }
                    double s10r = (double)s10ru;
                    double s10g = (double)s10gu;
                    double s10b = (double)s10bu;
                    double s10a = (double)s10au;
                    s10r = xFrac1 * s00r + xFrac0 * s10r;
                    s10g = xFrac1 * s00g + xFrac0 * s10g;
                    s10b = xFrac1 * s00b + xFrac0 * s10b;
                    s10a = xFrac1 * s00a + xFrac0 * s10a;
                    (uint s01ru, uint s01gu, uint s01bu, uint s01au) = src.At(sx0, sy1).Rgba();
                    if (srcMask != null)
                    {
                        (_, _, _, uint ma) = srcMask.At(smp.X + sx0, smp.Y + sy1).Rgba();
                        s01ru = s01ru * ma / 0xffff;
                        s01gu = s01gu * ma / 0xffff;
                        s01bu = s01bu * ma / 0xffff;
                        s01au = s01au * ma / 0xffff;
                    }
                    double s01r = (double)s01ru;
                    double s01g = (double)s01gu;
                    double s01b = (double)s01bu;
                    double s01a = (double)s01au;
                    (uint s11ru, uint s11gu, uint s11bu, uint s11au) = src.At(sx1, sy1).Rgba();
                    if (srcMask != null)
                    {
                        (_, _, _, uint ma) = srcMask.At(smp.X + sx1, smp.Y + sy1).Rgba();
                        s11ru = s11ru * ma / 0xffff;
                        s11gu = s11gu * ma / 0xffff;
                        s11bu = s11bu * ma / 0xffff;
                        s11au = s11au * ma / 0xffff;
                    }
                    double s11r = (double)s11ru;
                    double s11g = (double)s11gu;
                    double s11b = (double)s11bu;
                    double s11a = (double)s11au;
                    s11r = xFrac1 * s01r + xFrac0 * s11r;
                    s11g = xFrac1 * s01g + xFrac0 * s11g;
                    s11b = xFrac1 * s01b + xFrac0 * s11b;
                    s11a = xFrac1 * s01a + xFrac0 * s11a;
                    s11r = yFrac1 * s10r + yFrac0 * s11r;
                    s11g = yFrac1 * s10g + yFrac0 * s11g;
                    s11b = yFrac1 * s10b + yFrac0 * s11b;
                    s11a = yFrac1 * s10a + yFrac0 * s11a;
                    uint pr = (uint)s11r;
                    uint pg = (uint)s11g;
                    uint pb = (uint)s11b;
                    uint pa = (uint)s11a;
                    if (dstMask != null)
                    {
                        (uint qr, uint qg, uint qb, uint qa) = dst.At(dr.Min.X + dx, dr.Min.Y + dy).Rgba();
                        (_, _, _, uint ma) = dstMask.At(dmp.X + dr.Min.X + dx, dmp.Y + dr.Min.Y + dy).Rgba();
                        pr = pr * ma / 0xffff;
                        pg = pg * ma / 0xffff;
                        pb = pb * ma / 0xffff;
                        pa = pa * ma / 0xffff;
                        uint pa1 = 0xffff - ma;
                        dstColorRGBA64 = new Rgba64((ushort)(qr * pa1 / 0xffff + pr), (ushort)(qg * pa1 / 0xffff + pg), (ushort)(qb * pa1 / 0xffff + pb), (ushort)(qa * pa1 / 0xffff + pa));
                        dst.Set(dr.Min.X + dx, dr.Min.Y + dy, dstColorRGBA64);
                    }
                    else
                    {
                        dstColorRGBA64 = new Rgba64((ushort)pr, (ushort)pg, (ushort)pb, (ushort)pa);
                        dst.Set(dr.Min.X + dx, dr.Min.Y + dy, dstColorRGBA64);
                    }
                }
            }
        }


        internal static void KernelTransform(Kernel q, IWritableImage dst, Aff3 s2d, IImage src, Rect sr, Op op, Options? opts)
        {
            var o = opts ?? default;

            Rect dr = TransformRect(s2d, sr);
            // adr is the affected destination pixels.
            Rect adr = dst.Bounds().Intersect(dr);
            (adr, o.DstMask) = ScaleOps.ClipAffectedDestRect(adr, o.DstMask, o.DstMaskP);
            if (adr.Empty() || sr.Empty())
            {
                return;
            }
            if (op == Op.Over && o.SrcMask == null && ScaleOps.Opaque(src))
            {
                op = Op.Src;
            }
            var d2s = Invert(s2d);
            // bias is a translation of the mapping from dst coordinates to src
            // coordinates such that the latter temporarily have non-negative X
            // and Y coordinates. This allows us to write int(f) instead of
            // int(math.Floor(f)), since "round to zero" and "round down" are
            // equivalent when f >= 0, but the former is much cheaper. The X--
            // and Y-- are because the TransformLeaf methods have a "sx -= 0.5"
            // adjustment.
            Point bias = TransformRect(d2s, adr).Min;
            bias = new Point(bias.X - 1, bias.Y - 1);
            d2s = new Aff3(d2s[0], d2s[1], d2s[2] - bias.X, d2s[3], d2s[4], d2s[5] - bias.Y);
            // Make adr relative to dr.Min.
            adr = adr.Sub(dr.Min);

            if (src is UniformImage u && o.DstMask != null && o.SrcMask != null && sr.In(src.Bounds()))
            {
                TransformUniform(dst, dr, adr, d2s, u, sr, bias, op);
                return;
            }

            double xscale = Abs(d2s[0]);
            if (xscale < Abs(d2s[1]))
            {
                xscale = Abs(d2s[1]);
            }
            double yscale = Abs(d2s[3]);
            if (yscale < Abs(d2s[4]))
            {
                yscale = Abs(d2s[4]);
            }

            // sr is the source pixels. If it extends beyond the src bounds,
            // we cannot use the type-specific fast paths, as they access
            // the Pix fields directly without bounds checking.
            //
            // Similarly, the fast paths assume that the masks are nil.
            if (o.DstMask != null || o.SrcMask != null || !sr.In(src.Bounds()))
            {
                switch (op)
                {
                    case Op.Over: KernelTransform_Image_Image_Over(q, dst, dr, adr, d2s, src, sr, bias, xscale, yscale, o); break;
                    case Op.Src: KernelTransform_Image_Image_Src(q, dst, dr, adr, d2s, src, sr, bias, xscale, yscale, o); break;
                }
            }
            else
            {
                switch (op)
                {
                    case Op.Over:
                        switch (dst)
                        {
                            case RgbaImage d:
                                switch (src)
                                {
                                    case NrgbaImage s:
                                        KernelTransform_Rgba_Nrgba_Over(q, d, dr, adr, d2s, s, sr, bias, xscale, yscale, o);
                                        break;
                                    case RgbaImage s:
                                        KernelTransform_Rgba_Rgba_Over(q, d, dr, adr, d2s, s, sr, bias, xscale, yscale, o);
                                        break;
                                    case IRgba64Image s:
                                        KernelTransform_Rgba_Rgba64_Over(q, d, dr, adr, d2s, s, sr, bias, xscale, yscale, o);
                                        break;
                                    default:
                                        KernelTransform_Rgba_Image_Over(q, d, dr, adr, d2s, src, sr, bias, xscale, yscale, o);
                                        break;
                                }
                                break;
                            case ITargetRgba64Image d:
                                switch (src)
                                {
                                    case IRgba64Image s:
                                        KernelTransform_Rgba64_Rgba64_Over(q, d, dr, adr, d2s, s, sr, bias, xscale, yscale, o);
                                        break;
                                }
                                break;
                            default:
                                switch (src)
                                {
                                    default:
                                        KernelTransform_Image_Image_Over(q, dst, dr, adr, d2s, src, sr, bias, xscale, yscale, o);
                                        break;
                                }
                                break;
                        }
                        break;
                    case Op.Src:
                        switch (dst)
                        {
                            case RgbaImage d:
                                switch (src)
                                {
                                    case GrayImage s:
                                        KernelTransform_Rgba_Gray_Src(q, d, dr, adr, d2s, s, sr, bias, xscale, yscale, o);
                                        break;
                                    case NrgbaImage s:
                                        KernelTransform_Rgba_Nrgba_Src(q, d, dr, adr, d2s, s, sr, bias, xscale, yscale, o);
                                        break;
                                    case RgbaImage s:
                                        KernelTransform_Rgba_Rgba_Src(q, d, dr, adr, d2s, s, sr, bias, xscale, yscale, o);
                                        break;
                                    case YCbCrImage s:
                                        switch (s.SubsampleRatio)
                                        {
                                            default:
                                                KernelTransform_Rgba_Image_Src(q, d, dr, adr, d2s, s, sr, bias, xscale, yscale, o);
                                                break;
                                            case YCbCrSubsampleRatio.Ratio444:
                                                KernelTransform_Rgba_YCbCr444_Src(q, d, dr, adr, d2s, s, sr, bias, xscale, yscale, o);
                                                break;
                                            case YCbCrSubsampleRatio.Ratio422:
                                                KernelTransform_Rgba_YCbCr422_Src(q, d, dr, adr, d2s, s, sr, bias, xscale, yscale, o);
                                                break;
                                            case YCbCrSubsampleRatio.Ratio420:
                                                KernelTransform_Rgba_YCbCr420_Src(q, d, dr, adr, d2s, s, sr, bias, xscale, yscale, o);
                                                break;
                                            case YCbCrSubsampleRatio.Ratio440:
                                                KernelTransform_Rgba_YCbCr440_Src(q, d, dr, adr, d2s, s, sr, bias, xscale, yscale, o);
                                                break;
                                        }
                                        break;
                                    case IRgba64Image s:
                                        KernelTransform_Rgba_Rgba64_Src(q, d, dr, adr, d2s, s, sr, bias, xscale, yscale, o);
                                        break;
                                    default:
                                        KernelTransform_Rgba_Image_Src(q, d, dr, adr, d2s, src, sr, bias, xscale, yscale, o);
                                        break;
                                }
                                break;
                            case ITargetRgba64Image d:
                                switch (src)
                                {
                                    case IRgba64Image s:
                                        KernelTransform_Rgba64_Rgba64_Src(q, d, dr, adr, d2s, s, sr, bias, xscale, yscale, o);
                                        break;
                                }
                                break;
                            default:
                                switch (src)
                                {
                                    default:
                                        KernelTransform_Image_Image_Src(q, dst, dr, adr, d2s, src, sr, bias, xscale, yscale, o);
                                        break;
                                }
                                break;
                        }
                        break;
                }

            }
        }

        internal static void KernelTransform_Rgba_Gray_Src(Kernel q, RgbaImage dst, Rect dr, Rect adr, Aff3 d2s, GrayImage src, Rect sr, Point bias, double xscale, double yscale, Options o)
        {
            // When shrinking, broaden the effective kernel support so that we still
            // visit every source pixel.
            double xHalfWidth = q.Support, xKernelArgScale = 1.0;
            if (xscale > 1)
            {
                xHalfWidth *= xscale;
                xKernelArgScale = 1 / xscale;
            }
            double yHalfWidth = q.Support, yKernelArgScale = 1.0;
            if (yscale > 1)
            {
                yHalfWidth *= yscale;
                yKernelArgScale = 1 / yscale;
            }

            var xWeights = new double[1 + 2 * (int)DotMath.Ceiling(xHalfWidth)];
            var yWeights = new double[1 + 2 * (int)DotMath.Ceiling(yHalfWidth)];

            for (int dy = adr.Min.Y; dy < adr.Max.Y; dy++)
            {
                double dyf = dr.Min.Y + dy + 0.5;
                int d = (dr.Min.Y+dy-dst.Rect.Min.Y)*dst.Stride + (dr.Min.X+adr.Min.X-dst.Rect.Min.X)*4;
                for (int dx = adr.Min.X; dx < adr.Max.X; dx++, d += 4) { 
                    double dxf = dr.Min.X + dx + 0.5;
                    double sx = d2s[0] * dxf + d2s[1] * dyf + d2s[2];
