        internal static void KernelTransform_Rgba64_Rgba64_Over(Kernel q, ITargetRgba64Image dst, Rect dr, Rect adr, Aff3 d2s, IRgba64Image src, Rect sr, Point bias, double xscale, double yscale, Options o)
        {
            // When shrinking, broaden the effective kernel support so that we still
            // visit every source pixel.
            double xHalfWidth = q.Support, xKernelArgScale = 1.0;
            if (xscale > 1)
            {
                xHalfWidth *= xscale;
                xKernelArgScale = 1 / xscale;
            }
            double yHalfWidth = q.Support, yKernelArgScale = 1.0;
            if (yscale > 1)
            {
                yHalfWidth *= yscale;
                yKernelArgScale = 1 / yscale;
            }

            var xWeights = new double[1 + 2 * (int)DotMath.Ceiling(xHalfWidth)];
            var yWeights = new double[1 + 2 * (int)DotMath.Ceiling(yHalfWidth)];

            IImage? srcMask = o.SrcMask;
            Point smp = o.SrcMaskP;
            IImage? dstMask = o.DstMask;
            Point dmp = o.DstMaskP;
            Rgba64 dstColorRGBA64 = new Rgba64(0, 0, 0, 0);
            for (int dy = adr.Min.Y; dy < adr.Max.Y; dy++)
            {
                double dyf = dr.Min.Y + dy + 0.5;
                for (int dx = adr.Min.X; dx < adr.Max.X; dx++) { 
                    double dxf = dr.Min.X + dx + 0.5;
                    double sx = d2s[0] * dxf + d2s[1] * dyf + d2s[2];
                    double sy = d2s[3] * dxf + d2s[4] * dyf + d2s[5];
                    if (!new Point((int)sx + bias.X, (int)sy + bias.Y).In(sr))
                    {
                        continue;
                    }

                    // TODO: adjust the bias so that we can use int casts
                    // instead of Floor and Ceiling.
                    sx += bias.X;
                    sx -= 0.5;
                    int ix = (int)DotMath.Floor(sx - xHalfWidth);
                    if (ix < sr.Min.X)
                    {
                        ix = sr.Min.X;
                    }
                    int jx = (int)DotMath.Ceiling(sx + xHalfWidth);
                    if (jx > sr.Max.X)
                    {
                        jx = sr.Max.X;
                    }

                    double totalXWeight = 0.0;
                    for (int kx = ix; kx < jx; kx++)
                    {
                        double xWeight = 0.0;
                        double t = Abs((sx - kx) * xKernelArgScale);
                        if (t < q.Support)
                        {
                            xWeight = q.At(t);
                        }
                        xWeights[kx - ix] = xWeight;
                        totalXWeight += xWeight;
                    }
                    for (int x = 0; x < jx - ix; x++)
                    {
                        xWeights[x] /= totalXWeight;
                    }

                    sy += bias.Y;
                    sy -= 0.5;
                    int iy = (int)DotMath.Floor(sy - yHalfWidth);
                    if (iy < sr.Min.Y)
                    {
                        iy = sr.Min.Y;
                    }
                    int jy = (int)DotMath.Ceiling(sy + yHalfWidth);
                    if (jy > sr.Max.Y)
                    {
                        jy = sr.Max.Y;
                    }

                    double totalYWeight = 0.0;
                    for (int ky = iy; ky < jy; ky++)
                    {
                        double yWeight = 0.0;
                        double t = Abs((sy - ky) * yKernelArgScale);
                        if (t < q.Support)
                        {
                            yWeight = q.At(t);
                        }
                        yWeights[ky - iy] = yWeight;
                        totalYWeight += yWeight;
                    }
                    for (int y = 0; y < jy - iy; y++)
                    {
                        yWeights[y] /= totalYWeight;
                    }

                    double pr = 0, pg = 0, pb = 0, pa = 0;
                    for (int ky = iy; ky < jy; ky++)
                    {
                        double yWeight = yWeights[ky - iy];
                        if (yWeight != 0)
                        {
                            for (int kx = ix; kx < jx; kx++)
                            {
                                double w = xWeights[kx - ix] * yWeight;
                                if (w != 0)
                                {
                                    Rgba64 pu = src.Rgba64At(kx, ky);
                                    if (srcMask != null)
                                    {
                                        (_, _, _, uint ma) = srcMask.At(smp.X + kx, smp.Y + ky).Rgba();
                                        pu = new Rgba64((ushort)((uint)pu.R * ma / 0xffff), (ushort)((uint)pu.G * ma / 0xffff), (ushort)((uint)pu.B * ma / 0xffff), (ushort)((uint)pu.A * ma / 0xffff));
                                    }
                                    pr += (double)pu.R * w;
                                    pg += (double)pu.G * w;
                                    pb += (double)pu.B * w;
                                    pa += (double)pu.A * w;
                                }
                            }
                        }
                    }
                    if (pr > pa) { pr = pa; }
                    if (pg > pa) { pg = pa; }
                    if (pb > pa) { pb = pa; }
                    Rgba64 dstAt = dst.Rgba64At(dr.Min.X + dx, dr.Min.Y + dy);
                    uint pr0 = ScaleImpl.Fffftou(pr);
                    uint pg0 = ScaleImpl.Fffftou(pg);
                    uint pb0 = ScaleImpl.Fffftou(pb);
                    uint pa0 = ScaleImpl.Fffftou(pa);
                    if (dstMask != null)
                    {
                        (_, _, _, uint ma) = dstMask.At(dmp.X + dr.Min.X + dx, dmp.Y + dr.Min.Y + dy).Rgba();
                        pr0 = pr0 * ma / 0xffff;
                        pg0 = pg0 * ma / 0xffff;
                        pb0 = pb0 * ma / 0xffff;
                        pa0 = pa0 * ma / 0xffff;
                    }
                    uint pa1 = 0xffff - pa0;
                    dstColorRGBA64 = new Rgba64((ushort)((uint)dstAt.R * pa1 / 0xffff + pr0), (ushort)((uint)dstAt.G * pa1 / 0xffff + pg0), (ushort)((uint)dstAt.B * pa1 / 0xffff + pb0), (ushort)((uint)dstAt.A * pa1 / 0xffff + pa0));
                    dst.SetRgba64(dr.Min.X + dx, dr.Min.Y + dy, dstColorRGBA64);
                }
            }
        }

