    internal sealed partial class KernelScaler
    {
        public void Scale(IWritableImage dst, Rect dr, IImage src, Rect sr, Op op, Options? opts)
        {
            if (Dw != dr.Dx() || Dh != dr.Dy() || Sw != sr.Dx() || Sh != sr.Dy())
            {
                Kernel.Scale(dst, dr, src, sr, op, opts);
                return;
            }

            var o = opts ?? default;

            // adr is the affected destination pixels.
            Rect adr = dst.Bounds().Intersect(dr);
            (adr, o.DstMask) = ScaleOps.ClipAffectedDestRect(adr, o.DstMask, o.DstMaskP);
            if (adr.Empty() || sr.Empty())
            {
                return;
            }
            // Make adr relative to dr.Min.
            adr = adr.Sub(dr.Min);
            if (op == Op.Over && o.SrcMask == null && ScaleOps.Opaque(src))
            {
                op = Op.Src;
            }

            if (src is UniformImage && o.DstMask == null && o.SrcMask == null && sr.In(src.Bounds()))
            {
                DrawOps.Draw(dst, dr, src, src.Bounds().Min, op);
                return;
            }

            // Create a temporary buffer:
            // scaleX distributes the source image's columns over the temporary image.
            // scaleY distributes the temporary image's rows over the destination image.
            var tmp = new double[Dw * Sh * 4];

            // sr is the source pixels. If it extends beyond the src bounds,
            // we cannot use the type-specific fast paths, as they access
            // the Pix fields directly without bounds checking.
            //
            // Similarly, the fast paths assume that the masks are nil.
            if (o.SrcMask != null || !sr.In(src.Bounds()))
            {
                ScaleX_Image(tmp, src, sr, o);
            }
            else
            {
                switch (src)
                {
                    case GrayImage s:
                        ScaleX_Gray(tmp, s, sr, o);
                        break;
                    case NrgbaImage s:
                        ScaleX_Nrgba(tmp, s, sr, o);
                        break;
                    case RgbaImage s:
                        ScaleX_Rgba(tmp, s, sr, o);
                        break;
                    case YCbCrImage s:
                        switch (s.SubsampleRatio)
                        {
                            default:
                                ScaleX_Image(tmp, s, sr, o);
                                break;
                            case YCbCrSubsampleRatio.Ratio444:
                                ScaleX_YCbCr444(tmp, s, sr, o);
                                break;
                            case YCbCrSubsampleRatio.Ratio422:
                                ScaleX_YCbCr422(tmp, s, sr, o);
                                break;
                            case YCbCrSubsampleRatio.Ratio420:
                                ScaleX_YCbCr420(tmp, s, sr, o);
                                break;
                            case YCbCrSubsampleRatio.Ratio440:
                                ScaleX_YCbCr440(tmp, s, sr, o);
                                break;
                        }
                        break;
                    case IRgba64Image s:
                        ScaleX_Rgba64(tmp, s, sr, o);
                        break;
                    default:
                        ScaleX_Image(tmp, src, sr, o);
                        break;
                }

            }

            if (o.DstMask != null)
            {
                switch (op)
                {
                    case Op.Over: ScaleY_Image_Over(dst, dr, adr, tmp, o); break;
                    case Op.Src: ScaleY_Image_Src(dst, dr, adr, tmp, o); break;
                }
            }
            else
            {
                switch (op)
                {
                    case Op.Over:
                        switch (dst)
                        {
                            case RgbaImage d:
                                ScaleY_Rgba_Over(d, dr, adr, tmp, o);
                                break;
                            case ITargetRgba64Image d:
                                ScaleY_Rgba64_Over(d, dr, adr, tmp, o);
                                break;
                            default:
                                ScaleY_Image_Over(dst, dr, adr, tmp, o);
                                break;
                        }
                        break;
                    case Op.Src:
                        switch (dst)
                        {
                            case RgbaImage d:
                                ScaleY_Rgba_Src(d, dr, adr, tmp, o);
                                break;
                            case ITargetRgba64Image d:
                                ScaleY_Rgba64_Src(d, dr, adr, tmp, o);
                                break;
                            default:
                                ScaleY_Image_Src(dst, dr, adr, tmp, o);
                                break;
                        }
                        break;
                }

            }
        }

        internal void ScaleX_Gray(double[] tmp, GrayImage src, Rect sr, Options o)
        {
            int t = 0;
            for (int y = 0; y < Sh; y++)
            {
                for (int s = 0; s < Horizontal.Sources.Length; s++)
                {
                    var b = Horizontal.Sources[s];
                    double pr = 0;
                    for (int ci = b.I; ci < b.J; ci++)
                    {
                        var cc = Horizontal.Contribs[ci];
                        int pi = (sr.Min.Y + y-src.Rect.Min.Y)*src.Stride + (sr.Min.X + cc.Coord-src.Rect.Min.X);
                        uint pru = (uint)src.Pix.Span[pi] * 0x101;
                        pr += (double)pru * cc.Weight;
                    }
                    pr *= b.InvTotalWeightFFFF;
                    int t4 = t * 4;
                    tmp[t4 + 0] = pr;
                    tmp[t4 + 1] = pr;
                    tmp[t4 + 2] = pr;
                    tmp[t4 + 3] = 1.0;
                    t++;
                }
            }
        }
        internal void ScaleX_Nrgba(double[] tmp, NrgbaImage src, Rect sr, Options o)
        {
            int t = 0;
            for (int y = 0; y < Sh; y++)
            {
                for (int s = 0; s < Horizontal.Sources.Length; s++)
                {
                    var b = Horizontal.Sources[s];
                    double pr = 0, pg = 0, pb = 0, pa = 0;
                    for (int ci = b.I; ci < b.J; ci++)
                    {
                        var cc = Horizontal.Contribs[ci];
                        int pi = (sr.Min.Y + y-src.Rect.Min.Y)*src.Stride + (sr.Min.X + cc.Coord-src.Rect.Min.X)*4;
                        uint pau = (uint)src.Pix.Span[pi + 3] * 0x101;
                        uint pru = (uint)src.Pix.Span[pi + 0] * pau / 0xff;
                        uint pgu = (uint)src.Pix.Span[pi + 1] * pau / 0xff;
                        uint pbu = (uint)src.Pix.Span[pi + 2] * pau / 0xff;
                        pr += (double)pru * cc.Weight;
                        pg += (double)pgu * cc.Weight;
                        pb += (double)pbu * cc.Weight;
                        pa += (double)pau * cc.Weight;
                    }
                    int t4 = t * 4;
                    tmp[t4 + 0] = pr * b.InvTotalWeightFFFF;
                    tmp[t4 + 1] = pg * b.InvTotalWeightFFFF;
                    tmp[t4 + 2] = pb * b.InvTotalWeightFFFF;
                    tmp[t4 + 3] = pa * b.InvTotalWeightFFFF;
                    t++;
                }
            }
        }
        internal void ScaleX_Rgba(double[] tmp, RgbaImage src, Rect sr, Options o)
        {
            int t = 0;
            for (int y = 0; y < Sh; y++)
            {
                for (int s = 0; s < Horizontal.Sources.Length; s++)
                {
                    var b = Horizontal.Sources[s];
                    double pr = 0, pg = 0, pb = 0, pa = 0;
                    for (int ci = b.I; ci < b.J; ci++)
                    {
                        var cc = Horizontal.Contribs[ci];
                        int pi = (sr.Min.Y + y-src.Rect.Min.Y)*src.Stride + (sr.Min.X + cc.Coord-src.Rect.Min.X)*4;
                        uint pru = (uint)src.Pix.Span[pi + 0] * 0x101;
                        uint pgu = (uint)src.Pix.Span[pi + 1] * 0x101;
                        uint pbu = (uint)src.Pix.Span[pi + 2] * 0x101;
                        uint pau = (uint)src.Pix.Span[pi + 3] * 0x101;
                        pr += (double)pru * cc.Weight;
                        pg += (double)pgu * cc.Weight;
